<?php
$collections=load_collections();$editId=(int)($_GET['edit'] ?? 0);$deleteId=(int)($_GET['delete'] ?? 0);$edit=null;$deleting=null;
foreach($collections as $row){if((int)$row['id']===$editId)$edit=$row;if((int)$row['id']===$deleteId)$deleting=$row;}
$showForm=isset($_GET['new'])||$edit;$visible=count(array_filter($collections,static fn($row)=>$row['is_visible']));
$suggestions=['Pria','Unisex','Wanita'];foreach($products as $p){$suggestions[]=$p['category'];$suggestions=array_merge($suggestions,array_map('trim',preg_split('/[·,|]+/u',$p['notes'] ?? '') ?: []));}$suggestions=array_unique(array_filter($suggestions));
?>
<div class="erp-collection-kpis"><article><span>Total Kategori</span><strong><?= count($collections) ?></strong></article><article><span>Tampil di Toko</span><strong><?= $visible ?></strong></article><article><span>Disembunyikan</span><strong><?= count($collections)-$visible ?></strong></article></div>
<?php if($deleting): ?>
<section class="erp-card erp-form-narrow"><div class="erp-card-head"><div><h2>Hapus Kategori</h2><p>Kategori akan hilang dari Explore Collections. Produk tidak dihapus.</p></div></div><form method="post" class="erp-form"><input type="hidden" name="action" value="admin_collection_delete"><input type="hidden" name="collection_id" value="<?= $deleteId ?>"><input type="hidden" name="csrf" value="<?= e(admin_management_csrf()) ?>"><label>Ketik nama kategori: <?= e($deleting['label']) ?><input name="confirmation" required autocomplete="off"></label><button class="erp-btn erp-btn-danger">Hapus Kategori</button><a href="?page=admin&tab=collections">Batal</a></form></section>
<?php endif; ?>
<?php if($showForm): $p=$edit ?? ['label'=>'','filter_field'=>'gender','filter_value'=>'','sort_order'=>count($collections)+1,'is_visible'=>1,'image'=>null]; ?>
<section class="erp-card"><div class="erp-card-head"><div><h2><?= $edit?'Edit Kategori':'Tambah Kategori' ?></h2><p>Atur tampilan panel dan produk yang ditampilkan ketika kategori diklik.</p></div><a href="?page=admin&tab=collections">Kembali</a></div>
<div class="erp-collection-editor"><form method="post" enctype="multipart/form-data" class="erp-form"><input type="hidden" name="action" value="admin_collection_save"><input type="hidden" name="collection_id" value="<?= (int)($p['id'] ?? 0) ?>"><input type="hidden" name="csrf" value="<?= e(admin_management_csrf()) ?>">
<label>Nama yang tampil di toko<input name="label" maxlength="80" required value="<?= e($p['label']) ?>" placeholder="Contoh: PRIA"></label>
<div class="erp-form-row"><label>Jenis filter<select name="filter_field"><?php foreach(['gender'=>'Gender','category'=>'Kategori produk','notes'=>'Notes / aroma','all'=>'Semua produk'] as $value=>$label): ?><option value="<?= e($value) ?>" <?= $p['filter_field']===$value?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><label>Nilai filter<input name="filter_value" maxlength="80" list="collection-filter-values" value="<?= e($p['filter_value']) ?>" placeholder="Pria, Unisex, Wanita, Woody..."></label></div>
<datalist id="collection-filter-values"><?php foreach($suggestions as $value): ?><option value="<?= e($value) ?>"></option><?php endforeach; ?></datalist>
<p class="erp-collection-help">Nama panel bebas. Filter gender harus Pria, Unisex, atau Wanita. Untuk kategori dan notes, gunakan nilai yang sama dengan data produk. Jika memilih Semua produk, nilai filter diabaikan.</p>
<label>Urutan tampilan<input type="number" name="sort_order" min="0" max="9999" required value="<?= (int)$p['sort_order'] ?>"><small>Angka lebih kecil tampil lebih dahulu.</small></label>
<label class="management-check"><input type="checkbox" name="is_visible" <?= $p['is_visible']?'checked':'' ?>> Tampilkan di Explore Collections</label>
<label>Gambar kategori (opsional)<input type="file" name="image" accept="image/jpeg,image/png,image/webp"><small>JPG, PNG, atau WebP, maksimal 5 MB. Tanpa gambar, panel memakai gradasi iridescent.</small></label>
<?php if($p['image']): ?><label class="management-check"><input type="checkbox" name="remove_image"> Hapus gambar dan gunakan gradasi</label><?php endif; ?>
<button class="erp-btn">Simpan Kategori</button></form>
<aside class="erp-collection-preview"><h3>Tampilan Saat Ini</h3><div class="erp-collection-preview-panel"><?php if($p['image']): ?><img src="<?= e($p['image']) ?>" alt="<?= e($p['label']) ?>"><?php endif; ?><strong><?= e($p['label'] ?: 'NAMA KATEGORI') ?></strong></div><p>Preview diperbarui setelah perubahan disimpan.</p><?php if($edit): ?><a href="<?= e(collection_url($p)) ?>" target="_blank" rel="noopener">Lihat <?= collection_product_count($p,$products) ?> produk terkait</a><?php endif; ?></aside></div>
</section>
<?php endif; ?>
<section class="erp-card"><div class="erp-card-head"><div><h2>Daftar Kategori & Koleksi</h2><p>Urutan di bawah sama dengan urutan kategori pada toko.</p></div><div class="management-row-actions"><a href="?page=home" target="_blank" rel="noopener">Lihat Toko</a><a class="erp-btn" href="?page=admin&tab=collections&new=1">Tambah Kategori</a></div></div><div class="erp-table-wrap"><table><thead><tr><th>Kategori</th><th>Filter Produk</th><th>Produk Terkait</th><th>Urutan</th><th>Tampilan</th><th>Aksi</th></tr></thead><tbody>
<?php if(!$collections): ?><tr><td colspan="6">Belum ada kategori. Tambahkan kategori untuk ditampilkan di toko.</td></tr><?php endif; ?>
<?php foreach($collections as $row): ?><tr><td><div class="erp-collection-name"><?php if($row['image']): ?><img src="<?= e($row['image']) ?>" alt=""><?php else: ?><span class="erp-collection-swatch" aria-hidden="true"></span><?php endif; ?><strong><?= e($row['label']) ?></strong></div></td><td><?= e(['gender'=>'Gender','category'=>'Kategori','notes'=>'Aroma','all'=>'Semua produk'][$row['filter_field']]) ?><small><?= e($row['filter_value']) ?></small></td><td><a href="<?= e(collection_url($row)) ?>" target="_blank" rel="noopener"><?= collection_product_count($row,$products) ?> produk</a></td><td><?= (int)$row['sort_order'] ?></td><td><span class="erp-pill"><?= $row['is_visible']?'Tampil':'Disembunyikan' ?></span></td><td><div class="management-row-actions"><a href="?page=admin&tab=collections&edit=<?= (int)$row['id'] ?>">Edit</a><a href="?page=admin&tab=collections&delete=<?= (int)$row['id'] ?>">Hapus</a></div></td></tr><?php endforeach; ?>
</tbody></table></div></section>
